template <typename T, typename U, int N>
class SpecializedArray {
private:
    T storage[N];
public:
    using KeyType = U;

    SpecializedArray() = default;
    T& get(int index);
};

// Trailing return type for clarity (C++11+)
template <typename T, typename U, int N>
auto SpecializedArray<T, U, N>::get(int index) -> T& {
    return storage[index];
}
